package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSheet {
    public void respond(@Val Sheet sheet, ObjectResponse<SheetResponse> response) {
        response.send(SheetResponse.from(sheet));
    }
}
}

const enc = encodeURIComponent;

/**
 * A sheet's figures, every part of it read fresh from the store: as it is now, or, while the screen
 * shows an as-of date, as it stood at the end of that date (each read names it, and the sheet read
 * answers with that date as its today).
 */
export async function readFigures(sheetId: string): Promise<Figures> {
  const [sheet, people, claims, rates, settings, pools] = await Promise.all([
    getJson<Sheet>(`/api/sheets/${enc(sheetId)}`),
    getJson<{ people: Person[] }>(`/api/sheets/${enc(sheetId)}/people`).then((r) => r.people),
    getJson<{ claims: Claim[] }>(`/api/sheets/${enc(sheetId)}/claims`).then((r) => r.claims),
    getJson<{ rates: Rate[] }>(`/api/sheets/${enc(sheetId)}/rates`).then((r) => r.rates),
    getJson<Settings>(`/api/sheets/${enc(sheetId)}/settings`),
    getJson<{ pools: Pool[] }>(`/api/sheets/${enc(sheetId)}/pools`).then((r) => r.pools),
  ]);
  return sheetFigures(people, claims, rates, sheet.today, floorOf(settings), lateOf(settings, sheet.today), settings.cap ?? '', pools);
}

/**
 * The figures of each of the sheet's descendants: the sheets naming it as their parent, theirs, and
 * so on, each as the screen's as-of date shows it (as it is now while none is set). Kept under the
 * sheet's own key with the as-of date, so loading the sheet again, or changing the date, re-reads them all.
 */
export function useDescendantFigures(sheetId: string, asOf: string) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'descendants', asOf] as const,
    queryFn: async () => {
      const { descendants } = await getJson<{ descendants: string[] }>(`/api/sheets/${enc(sheetId)}/descendants`);
      return Promise.all(descendants.map(readFigures));
    },
  });
}
import { useNavigate, useSearch } from '@tanstack/react-router';

/**
 * Read and write ONE search-param key.
 *
 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
 * toggle, which row is selected. The control that owns a key is a self-contained file, and whoever
 * reads the key does so directly. Search params are an open namespace (declared once in
 * routes/__root.tsx), so a new key needs no schema change.
 *
 *     const [status, setStatus] = useSearchParam('status', asString);
 */
export function useSearchParam<T>(
  key: string,
  decode: (raw: unknown) => T,
): [T, (value: T | undefined) => void] {
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const navigate = useNavigate();

  const set = (value: T | undefined) => {
    void navigate({
      to: '.', // stay on the current route; only the search changes
      // Only the one key changes; every other param is left exactly as it was, so two controls
      // never clobber each other.
      search: (prev: Record<string, unknown>) => {
        const next = { ...prev };
        if (value === undefined || value === '') {
          delete next[key];
        } else {
          next[key] = value;
        }
        return next;
      },
      replace: true,
    });
  };

  return [decode(search[key]), set];
}

export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
export const asNumber = (raw: unknown): number | undefined => {
  const n = Number(raw);
  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
};
export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
